import {React,  useEffect, useState} from 'react';
import NavBar from '../components/navbar'
import Footer from '../components/footer';
import '../styles/details.css'
import {useParams} from "react-router-dom";
const ProjectDetailsPage = () =>{
    const [project,setProject] = useState({})
    const { id } = useParams();

    useEffect(()=>{
        window.scrollTo(0, 0);
    },[])
    
    useEffect(() => {
        fetch('projects.json')
        .then(response =>{ return response.json()})
        .then(data =>{
            data.allprojects.forEach((el)=>{
                if(el.code==id){
                    setProject(el);
                }
            })
        })
        .catch(error => console.error('Error fetching projects...'+error));
        }, []);
    return (
        <div className='detailspagebody'>
            <NavBar></NavBar>
            <section class="projectdetails-section project-intro-section">
            <img src={process.env.PUBLIC_URL + "/" + project.image} alt="Imagem principal do projeto" class="projectdetails-image"/>
            <div class="project-summary-container">
                <h2 class="section-title">Description</h2>
                <p class="project-description">Esta é uma breve descrição do projeto. Pode detalhar o objetivo, o problema que resolve e o seu impacto.</p>
                <p>{project.name}</p>
                <div class="project-info-container">
                    <p class="project-info-item"><strong>Type:</strong> {project.type}</p>
                    <p class="project-info-item"><strong>Year:</strong>  {project.year}</p>
                    <p class="project-info-item">Github Repository : <a href="#" class="project-link">{project.repository}</a></p>
                </div>
            </div>
        </section>

        <section class="projectdetails-section project-details-section">
            <h2 class="section-title">Details and Functionalities</h2>
            <p class="project-description">Aqui, pode descrever as funcionalidades principais do projeto em mais profundidade.</p>

            <h3 class="subsection-title">Technologies and tools used</h3>
            <ul class="technologies-list">
                {
                    !project || !project.technologies? <p>Loading technologies...</p>: (project.technologies.map((tech)=>(
                        <li class="technology-item">{tech}</li>
                    ))) 
                }
            </ul>
        </section>

        <section class="projectdetails-section project-screenshots-section">
            <h2 class="section-title">Capturas de Ecrã</h2>
            <div class="screenshots-grid">
                <img src="https://via.placeholder.com/400x250" alt="Captura de ecrã 1" class="screenshot-image"/>
                <img src="https://via.placeholder.com/400x250" alt="Captura de ecrã 2" class="screenshot-image"/>
                <img src="https://via.placeholder.com/400x250" alt="Captura de ecrã 3" class="screenshot-image"/>
            </div>
        </section>
            <Footer></Footer>

        </div>
    )
}

export default ProjectDetailsPage;